import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 기간은 신청 생성 일시(created_at) 기준이다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const STATUSES = ['신청', '승인', '반려'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건 형식이 올바르지 않습니다.');
  }
  return value;
}

function optionalDate(value: unknown): string | null {
  const text = optionalText(value);
  if (text !== null && !DATE_PATTERN.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return text;
}

function optionalInteger(value: unknown, message: string): number | null {
  const text = optionalText(value);
  if (text === null) {
    return null;
  }
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', message);
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr01604Controller {
  @Get('/certificates/ledger')
  async listCertificateLedger(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const query = checks.queryOf(req.query);
    const startDate = optionalDate(query['startDate']);
    const endDate = optionalDate(query['endDate']);
    const certificateFormId = optionalInteger(query['certificateFormId'], '증명서 양식 값이 올바르지 않습니다.');
    const employeeName = optionalText(query['employeeName']);
    const status = optionalText(query['status']);
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상태 값이 올바르지 않습니다.');
    }
    const page = optionalInteger(query['page'], '쪽 번호가 올바르지 않습니다.') ?? 0;
    let size = optionalInteger(query['size'], '쪽 크기가 올바르지 않습니다.') ?? DEFAULT_SIZE;
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      if (startDate !== null && endDate !== null) {
        const check = await db.query(
          'SELECT (CAST(:startDate AS date) > CAST(:endDate AS date)) AS "invalid"',
          { startDate, endDate },
        );
        if (check[0] && check[0]['invalid'] === true) {
          throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 시작일이 종료일보다 늦을 수 없습니다.');
        }
      }
      const where = `
        WHERE (CAST(:startDate AS date) IS NULL OR c.created_at >= CAST(:startDate AS date))
          AND (CAST(:endDate AS date) IS NULL OR c.created_at < CAST(:endDate AS date) + 1)
          AND (CAST(:certificateFormId AS bigint) IS NULL OR c.certificate_form_id = CAST(:certificateFormId AS bigint))
          AND (CAST(:employeeName AS text) IS NULL OR e.name LIKE '%' || CAST(:employeeName AS text) || '%')
          AND (CAST(:status AS text) IS NULL OR c.status = CAST(:status AS text))`;
      const filters = { startDate, endDate, certificateFormId, employeeName, status };
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM certificate c
         JOIN employee e ON e.employee_id = c.employee_id` + where,
        filters,
      );
      const total = Number(totalRows[0]?.['total'] ?? 0);
      const items = await db.query(
        `SELECT c.certificate_no AS "certificateNo",
                c.certificate_form_id AS "certificateFormId",
                c.employee_id AS "employeeId",
                c.created_at AS "createdAt",
                c.status AS "status",
                c.issued_date AS "issuedDate"
         FROM certificate c
         JOIN employee e ON e.employee_id = c.employee_id` + where + `
         ORDER BY c.created_at DESC, c.certificate_id DESC
         LIMIT :limit OFFSET :offset`,
        { ...filters, limit: size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }
}

