import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Num,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
  ErrorText,
  LookupSelect,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr01604Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [formId, setFormId] = useState<number | string>('');
  const [employeeName, setEmployeeName] = useState('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [dateError, setDateError] = useState('');

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/certificates/ledger', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [role, applied, pageNo],
  );

  const search = () => {
    if (startDate && endDate && startDate > endDate) {
      setDateError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      notify('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setDateError('');
    setPageNo(0);
    setApplied({ startDate, endDate, certificateFormId: formId, employeeName, status });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setFormId('');
    setEmployeeName('');
    setStatus('');
    setDateError('');
    setPageNo(0);
    setApplied({});
  };

  const columns = [
    { key: 'certificateNo', label: '증명서 번호' },
    {
      key: 'certificateFormId',
      label: '증명서 양식',
      render: (row: Row) => <RefName table="certificate_form" role={role} value={row.certificateFormId} />,
    },
    {
      key: 'employeeId',
      label: '신청자',
      render: (row: Row) => <RefName table="employee" role={role} value={row.employeeId} />,
    },
    {
      key: 'createdAt',
      label: '생성 일시',
      render: (row: Row) => <DateText value={row.createdAt} time />,
    },
    {
      key: 'status',
      label: '상태',
      render: (row: Row) => <Badge value={row.status} />,
    },
    {
      key: 'issuedDate',
      label: '발급일',
      render: (row: Row) => <DateText value={row.issuedDate} />,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Num value={data ? data.total : 0} />
      </section>
      <section className="box span-8">
        <h2>조회 조건</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="증명서 양식">
            <LookupSelect table="certificate_form" role={role} value={formId} onChange={setFormId} />
          </Field>
          <Field label="신청자 이름 또는 소속 부서">
            <TextInput value={employeeName} onChange={setEmployeeName} />
          </Field>
          <Field label="상태">
            <Select
              value={status}
              onChange={setStatus}
              options={[
                ['신청', '신청'],
                ['승인', '승인'],
                ['반려', '반려'],
              ]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {dateError ? <ErrorText text={dateError} /> : null}
      </section>
      <section className="box span-12">
        <h2>증명서 관리대장</h2>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={columns}
          rows={data ? data.items : []}
          onRowClick={(row) => setDetail(row)}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {detail ? (
        <Drawer title="증명서 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['증명서 번호', String(detail.certificateNo ?? '')],
              ['증명서 양식', <RefName table="certificate_form" role={role} value={detail.certificateFormId} />],
              ['신청자', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['생성 일시', <DateText value={detail.createdAt} time />],
              ['상태', <Badge value={detail.status} />],
              ['발급일', <DateText value={detail.issuedDate} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
